class Solution { public int minPathCost(int[][] grid,int[][] moveCost){int columns=grid[0].length;int[] dp=grid[0].clone();for(int row=0;row+1<grid.length;row++){int[] next=new int[columns];Arrays.fill(next,Integer.MAX_VALUE);for(int column=0;column<columns;column++)for(int nc=0;nc<columns;nc++)next[nc]=Math.min(next[nc],dp[column]+moveCost[grid[row][column]][nc]+grid[row+1][nc]);dp=next;}return Arrays.stream(dp).min().getAsInt();} }
